import AppKit
import UniformTypeIdentifiers

#if canImport(StampedeCore)
    import StampedeCore
#endif

@MainActor final class SystemClipboardClient: ClipboardClient {
    // nspasteboard.org markers, their legacy names, and vendor markers from 1Password 7, KeeWeb, and TypeIt4Me.
    static let excludedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
        "de.petermaurer.TransientPasteboardType", "Pasteboard generator type", "com.agilebits.onepassword",
        "net.antelle.keeweb", "com.typeit4me.clipping",
    ]

    private let pasteboard: NSPasteboard

    init(pasteboard: NSPasteboard = .general) { self.pasteboard = pasteboard }

    var revision: Int { pasteboard.changeCount }

    var accessState: ClipboardAccessState {
        if #available(macOS 15.4, *) {
            switch pasteboard.accessBehavior {
            case .alwaysAllow: return .allowed
            case .default: return .notDetermined
            case .ask: return .ask
            case .alwaysDeny: return .denied
            @unknown default: return .unknown
            }
        }
        return .allowed
    }

    var canReadInBackground: Bool { accessState == .allowed }

    func read() -> ClipboardRead {
        if #available(macOS 15.4, *), pasteboard.accessBehavior == .alwaysDeny { return .unavailable }
        guard let items = pasteboard.pasteboardItems else { return .unavailable }
        guard !items.isEmpty else { return .excluded }
        guard items.count == 1, let item = items.first else { return .excluded }
        guard !item.types.contains(where: { Self.excludedTypes.contains($0.rawValue) }) else { return .excluded }
        guard
            !item.types.contains(where: {
                UTType($0.rawValue)?.conforms(to: .pdf) == true
                    || ["com.apple.pasteboard.promised-file-url", "NSFilesPromisePboardType"].contains($0.rawValue)
            })
        else { return .excluded }
        // Some apps (including WeChat/Qt) publish both an image and a temporary-file URL.
        // Capture the explicit encoded image without opening or retaining the referenced file.
        for type in ClipboardImage.supportedTypes.map({ NSPasteboard.PasteboardType($0) })
        where item.types.contains(type) {
            guard let data = item.data(forType: type) else { return .unavailable }
            guard data.count <= ClipboardImage.maximumBytes else {
                return .rejectedImage(ImageProcessingError.tooLarge.localizedDescription)
            }
            // A URL is optional context supplied by the copying app, never inferred from browser tabs.
            let url = item.string(forType: .URL).flatMap(URL.init(string:))
            let host = url.flatMap { ["http", "https"].contains($0.scheme?.lowercased() ?? "") ? $0.host : nil }
            return .image(
                ImageCandidate(
                    type: type.rawValue,
                    data: data,
                    sourceApp: NSWorkspace.shared.frontmostApplication?.localizedName.map { String($0.prefix(64)) },
                    sourceHost: host.map { String($0.prefix(200)) }
                )
            )
        }
        guard
            !item.types.contains(where: {
                UTType($0.rawValue)?.conforms(to: .fileURL) == true || UTType($0.rawValue)?.conforms(to: .image) == true
            })
        else { return .excluded }
        guard item.types.contains(.string) else { return .excluded }
        guard let text = item.string(forType: .string) else { return .unavailable }
        return .text(text)
    }

    func writeImage(_ image: ClipboardImage) -> Bool {
        guard image.isValid, let data = image.data else { return false }
        let item = NSPasteboardItem()
        guard item.setData(data, forType: .init(image.type)) else { return false }
        pasteboard.clearContents()
        return pasteboard.writeObjects([item])
    }

    func clear() -> Int { pasteboard.clearContents() }

    func write(_ text: String) -> Bool {
        let item = NSPasteboardItem()
        guard item.setString(text, forType: .string) else { return false }
        // clearContents resets local-only options; ordinary writes remain eligible for Universal Clipboard.
        pasteboard.clearContents()
        return pasteboard.writeObjects([item])
    }
}
